add('N-006', 'Ⅱ-A', '서술절과 인용절', '최', S % '2025학년도 대학수학능력시험 39번',
    p('〈보기〉를 바탕으로 〈자료〉를 이해한 내용으로 적절한 것은?') +
    bogi(['간접 인용될 때 원 발화의 인칭·지시·시간 표현 등은 맥락에 따라 조정되며, 상대 높임의 종결 어미는 격식체/비격식체, 높임/낮춤에 관계없이 문장 종류별로 한 가지로 한정된다. \'보다\'를 예로 들면 \'본다고\'(평서), \'보냐고\'(의문), \'보라고\'(명령), \'보자고\'(청유)로 나타난다. 감탄형 어미는 평서형으로 실현된다(보는구나 → 본다고). 이런 이유로 서로 다른 발화도 간접 인용될 때 같은 형식을 가질 수 있다.'], '〈보기〉') +
    bogi(['○ 그는 그제 우리에게 <b>㉠</b>오늘은 청소를 같이 하자고 말했다.', '○ 김 선생은 <b>㉡</b>자기도 시를 좋아한다고 학생들에게 말했다.', '○ 어제 나한테 <b>㉢</b>네가 내일 퇴원을 할 수 있겠냐고 물었지?'], '자료'),
    ['㉠은 \'모레는\'이라는 부사어를 가진 발화를 인용한 것일 수 없다.', '㉠의 \'하자\'는 \'해요\'를 간접 인용한 것일 수 있다.', '㉡은 2인칭 주어를 가진 발화를 인용한 것일 수 있다.', '㉡의 \'좋아한다\'는 \'좋아합니다\'를 간접 인용한 것일 수 없다.', '㉢은 미래 시제 선어말 어미를 가진 발화를 인용한 것일 수 없다.'], 2,
    ['① 옳지 않다. 말한 때가 "그제"이고 인용절의 "오늘"은 발화한 현재이므로 원 발화는 "모레는 청소를 같이 하자"일 수 있다.', '② 옳다. 청유형 종결 어미는 비격식·높임 여부에 관계없이 간접 인용에서 "-자고"로 실현된다. "해요"(청유, 해요체)도 "하자고"로 인용된다.', '③ 옳지 않다. "자기"는 김 선생 자신을 가리키는 재귀 표현이므로 원 발화의 주어는 1인칭("나도")이다. 2인칭 주어("너도")는 학생들을 가리키는 말로 바뀐다.', '④ 옳지 않다. 평서형은 "좋아합니다"(하십시오체)도 "좋아한다고"로 인용된다.', '⑤ 옳지 않다. "있겠냐고"의 "-겠-"은 원 발화의 미래·추측 어미가 그대로 인용된 것일 수 있다.'],
    ref=[8], core='간접 인용: 인칭 · 시간 표현 재조정, 종결 어미는 문장 종류별 한 형태(-다고/-냐고/-라고/-자고)로 통합된다.')

# ================================================================= 2025 9월 39, 6월 37
add('N-007', 'Ⅱ-A', '안은문장의 종류', '최', S % '2025학년도 9월 모의평가 39번',
    p('〈보기〉의 [조건]이 모두 실현된 문장으로 적절한 것은?') + bogi(['<b>[조건]</b>', '○ 안긴절이 한 번만 나타날 것.', '○ 안긴절에는 짧은 부정 표현이 나타날 것.', '○ 안은문장은 사건시가 발화시보다 앞설 것.']),
    ['그는 한동안 차갑지 않은 음식만 먹었었다.', '그는 바쁜 업무들이 안 끝났다고 통보했다.', '나는 결코 포기를 하지 않겠다고 결심했다.', '나는 그 버스가 제때 못 올 것을 예상한다.', '나는 그가 못 읽은 소설을 이미 다 읽었다.'], 5,
    ['① 안긴절 "차갑지 않은"의 부정이 긴 부정(-지 않다)이다.', '② 안긴절이 "바쁜"(관형사절)과 "…안 끝났다고"(인용절) 두 개이다.', '③ 안긴절에 짧은 부정이 없다(긴 부정 "하지 않겠다고"). 안은문장 "결심했다"는 과거이지만 조건 ②를 어긴다.', '④ 안은문장 "예상한다"가 현재이다.', '⑤ 안긴절은 관형사절 "그가 못 읽은" 하나, 짧은 부정 "못", 안은문장 "읽었다"는 과거로 세 조건을 모두 만족한다.'],
    ref=[8], core='조건 표는 문장마다 ○ × 표를 만들어 하나씩 소거한다.')

add('N-008', 'Ⅱ-A', '서술어의 자릿수', '상', S % '2025학년도 6월 모의평가 37번', p('밑줄 친 서술어가 필수적으로 요구하는 문장 성분의 개수 및 종류가 같은 것끼리 짝지어진 것은?'),
    ['할아버지는 형님 댁에 <u>계신다</u>. / 여객선이 <u>도착한</u> 항구엔 안개가 꼈다.', '저 친구는 불평이 <u>그칠</u> 날이 없다. / 그는 배에서 <u>내리는</u> 장면을 상상했다.', '나는 이 호박을 죽으로 <u>만들</u> 것이다. / 아버지는 뜬눈으로 밤을 <u>새웠다</u>.', '얼음으로 <u>된</u> 성이 나타났다. / 그는 남이 <u>아니고</u> 가족이다.', '그의 신중함은 아무래도 <u>지나쳤다</u>. / 언니는 간이역만 <u>지나치는</u> 기차를 봤다.'], 1,
    ['① 같다. "계신다"는 주어 + 필수적 부사어("형님 댁에"), "도착한"도 주어("여객선이") + 필수적 부사어("항구에")를 요구한다.', '② 다르다. "그칠"은 주어 한 자리, "내리는"은 주어 + 필수적 부사어("배에서")이다.', '③ 다르다. "만들"은 주어·목적어·필수적 부사어(세 자리), "새웠다"는 주어·목적어(두 자리).', '④ 다르다. "된"은 주어 + 필수적 부사어("얼음으로"), "아니고"는 주어 + 보어("남이").', '⑤ 다르다. "지나쳤다"는 주어 한 자리, "지나치는"은 주어 + 목적어("간이역만").'],
    ref=[4], core='서술어의 자릿수와 필수 성분의 종류를 모두 비교한다.', vertical=True)

# ================================================================= 2024 수능 39 · 9월 38 · 6월 37
add('N-009', 'Ⅱ-A', '관형어와 부사어', '최', S % '2024학년도 대학수학능력시험 39번',
    p('〈학습 활동〉을 수행한 결과로 적절한 것은?') +
    bogi(['부사어는 부사, 체언 + 조사, 용언의 활용형 등으로 실현되며, 수식하는 성분은 서술어, 부사어, 관형어 등이다. (예: 차가 간다 → 차가 <u>잘</u> 간다.) 다음 [조건] 중 두 가지를 만족하도록 부사어를 넣어 문장을 수정해 보자.',
          '<b>㉠</b> 부사어를 수식하기 위해 부사를 부사어로 쓴 문장', '<b>㉡</b> 관형어를 수식하기 위해 용언 활용형을 부사어로 쓴 문장', '<b>㉢</b> 관형어를 수식하기 위해 부사를 부사어로 쓴 문장', '<b>㉣</b> 서술어를 수식하기 위해 \'체언 + 조사\'를 부사어로 쓴 문장', '<b>㉤</b> 서술어를 수식하기 위해 용언 활용형을 부사어로 쓴 문장']),
    ['<b>㉠, ㉡</b> 웃는 아기가 귀엽게 걷는다. → 방긋이 웃는 아기가 참 귀엽게 걷는다.', '<b>㉠, ㉢</b> 화가가 굵은 선을 쭉 그었다. → 화가가 조금 굵은 선을 세로로 쭉 그었다.', '<b>㉡, ㉤</b> 그를 싫어하는 사람이 있다. → 그를 무턱대고 싫어하는 사람이 많이 있다.', '<b>㉢, ㉣</b> 딴 사람이 그 문제를 해결했다. → 전혀 딴 사람이 그 문제를 한순간에 해결했다.', '<b>㉣, ㉤</b> 영미는 그 일을 처리했다. → 영미는 그 일을 원칙대로 깔끔히 처리했다.'], 4,
    ['① "참"(부사)이 부사어 "귀엽게"를 수식(㉠ ○), "방긋이"(부사)는 서술어가 아니라 관형어 "웃는"을 수식(㉢)이다. ㉡이 아니다.', '② "조금"(부사)이 관형어 "굵은"을 수식(㉢ ○)하지만, 부사어를 수식하는 부사(㉠)는 없다.', '③ "무턱대고"는 서술어 "싫어하는"을 수식(㉤ 성격)하고 "많이"는 서술어 "있다"를 수식한다. 관형어를 수식하는 용언 활용형 부사어(㉡)는 없다.', '④ "전혀"(부사)가 관형어 "딴"을 수식(㉢ ○), "한순간에"(체언 + 조사)가 서술어 "해결했다"를 수식(㉣ ○)한다. 적절하다.', '⑤ "원칙대로"는 ㉣ ○이지만 "깔끔히"는 용언 활용형이 아니라 부사이다(㉤ ×).'],
    ref=[5], core='부사어가 무엇을 수식하는지(서술어 · 부사어 · 관형어)와 어떤 모양인지(부사 · 체언 + 조사 · 용언 활용형)를 짝지어 확인한다.')

add('N-010', 'Ⅱ-B', '높임 표현의 종합 분석', '상', S % '2024학년도 9월 모의평가 38번',
    p('〈보기〉의 ㉠~㉢에 들어갈 수 있는 내용으로 적절하지 않은 것은?') +
    bogi(['<b>선생님</b>: 능동·피동, 주동·사동 표현에서 높임 표현과 시간 표현이 어떻게 나타나는지 탐구해 봅시다.', 'ⓐ 형이 동생을 업었다. ⓑ 동생이 형에게 업혔다. ⓒ 나는 동생에게 책을 읽혔다. ⓓ 나는 동생이 책을 읽게 했다.',
          '○ ⓐ, ⓑ에서 \'형\'을 높임 대상인 \'어머니\'로 바꿀 때 서술어에 생기는 차이는? → 학생: [㉠]', '○ ⓒ나 ⓓ에서 \'동생\'을 \'할머니\'로 바꾸면? → 학생: [㉡]', '○ ⓐ, ⓑ, ⓒ의 서술어에서 \'-었-\'을 \'-고 있-\'으로 바꾸면 어떤 의미를 나타낼까요? ⓐ와 ⓑ의 차이점이나 ⓐ와 ⓒ의 공통점을 말해 봅시다. → 학생: [㉢]']),
    ['㉠: ⓐ에서는 서술어에 \'-으시-\'를 넣어야 하지만, ⓑ에서는 \'-시-\'를 넣지 않습니다.', '㉡: ⓒ에서는 \'동생에게\'를 \'할머니께\'로 바꾸고, \'읽혔다\'에 \'-시-\'를 넣어야 합니다.', '㉡: ⓓ에서는 \'동생이\'를 \'할머니께서\'로 바꾸고, \'읽게\'에 \'-으시-\'를 넣어야 합니다.', '㉢: ⓐ는 동작의 완료 후 상태 지속의 의미를 나타낼 수 있지만, ⓑ는 그럴 수 없습니다.', '㉢: ⓐ와 ⓒ는 모두 동작의 진행 의미를 나타낼 수 있습니다.'], 2,
    ['① 적절하다. ⓐ는 주어 "어머니"를 높이므로 "업으셨다"로, ⓑ는 주어가 "동생"이고 "어머니께"는 부사어이므로 "-시-"를 넣지 않는다.', '② 적절하지 않다. ⓒ의 "읽혔다"의 주어는 "나"이다. "-시-"를 넣으면 주어 "나"를 높이는 말이 되어 부적절하다. 피사동주(부사어)인 "할머니께"를 높이려면 "-시-"가 아니라 다른 방식이 필요하다.', '③ 적절하다. ⓓ의 "읽게"의 의미상 주어가 "할머니"이므로 "-으시-"가 어울린다("할머니께서 책을 읽으시게 했다").', '④ 적절하다. 착용 동사와 비슷한 "업다"는 "업고 있다"가 진행 / 결과 상태 지속으로 해석되고, "업혀 있다"는 피동으로 진행이 아니라 상태 지속이다.', '⑤ 적절하다. "업고 있다", "읽히고 있다"는 모두 진행의 뜻을 나타낼 수 있다.'],
    ref=[2, 6], core='"-시-"는 문장의 주어를 높인다. 피동문의 부사어, 사동문의 피사동주는 "-시-"로 높일 수 없다.')

add('N-011', 'Ⅱ-B', '시제의 이해', '상', S % '2024학년도 6월 모의평가 37번',
    p('〈학습 활동〉의 ㉠~㉢에 들어갈 예문으로 적절한 것은?') +
    bogi(['다음 조건 중 두 가지를 모두 만족하는 문장을 찾아보자.', 'ⓐ 현재 시제만 쓰일 것  ⓑ 서술어의 자릿수가 둘일 것  ⓒ 안긴문장이 부사어로 기능할 것']) +
    tbl(['실현 조건', '예문'], [['ⓐ, ⓑ', '㉠'], ['ⓐ, ⓒ', '㉡'], ['ⓑ, ⓒ', '㉢']]),
    ['㉠: 그 집 마당에는 감나무 한 그루가 자란다.', '㉠: 선생님께서는 여전히 학교 근처에 사시는지요?', '㉡: 산중에 있으므로 여기는 도시보다 조용합니다.', '㉡: 오늘부터 아침으로 과일만 먹기로 마음먹었니?', '㉢: 오래전 큰아버지께 받은 책에 곰팡이가 슬었어.'], 2,
    ['① 현재 시제이지만 "자란다"는 주어만 필요한 한 자리 서술어이므로 ⓑ를 만족하지 못한다.', '② 현재 시제만 쓰였고("사시는지요"), "사시는"은 주어 + 필수적 부사어("학교 근처에")의 두 자리 서술어이다. ㉠에 적절하다.', '③ "있으므로"로 이어진 절은 종속적으로 이어진 절로 보아 안긴문장이 아니다(부사어로 기능하는 안긴문장 ×).', '④ "마음먹었니"는 과거이므로 ⓐ를 만족하지 못한다.', '⑤ "받은"과 "슬었어"는 과거이고, "받은 책"은 관형사절이어서 부사어로 기능하는 안긴문장이 아니다.'],
    ref=[3], core='조건을 문장마다 ○ × 로 체크한다. 시제, 서술어의 자릿수, 안긴문장의 기능을 따로 판단한다.')

add('N-012', 'Ⅱ-A', '안은문장의 종류', '최', S % '2023학년도 대학수학능력시험 39번',
    p('㉠~㉣의 문장 성분과 문장 구조에 대한 설명으로 적절한 것은?') +
    bogi(['<b>㉠</b> 나는 내 친구가 보낸 책을 제시간에 받기를 바란다.', '<b>㉡</b> 나는 테니스 배우기가 재미있다고 친구에게 말했다.', '<b>㉢</b> 이 식당은 우리 가족이 점심을 먹은 식당이 아니다.', '<b>㉣</b> 그녀는 아름다운 관광지를 신이 닳도록 돌아다녔다.']),
    ['㉠에는 필수적 부사어가 생략된 안긴문장이 있고, ㉡에는 주어가 생략된 안긴문장이 있다.', '㉠과 ㉡에는 모두, 주어 기능을 하는 명사절이 있다.', '㉠과 ㉢에는 모두, 주어가 생략된 안긴문장이 있다.', '㉢에는 보어 기능을 하는 안긴문장이 있고, ㉣에는 부사어 기능을 하는 안긴문장이 있다.', '㉢과 ㉣에는 모두, 목적어가 생략된 관형사절이 있다.'], 1,
    ['① 적절하다. ㉠의 "내 친구가 보낸"은 "친구가 (나에게) 책을 보냈다"에서 필수적 부사어 "나에게"가 생략된 관형사절이다. ㉡의 "테니스 배우기"는 "(내가) 테니스를 배우기"에서 주어가 생략된 명사절이다.', '② ㉠의 "받기를"은 목적어 기능의 명사절이다.', '③ ㉢의 "우리 가족이 점심을 먹은"에는 주어가 있고 생략된 것은 부사어("식당에서")이다.', '④ ㉢에서 보어 기능을 하는 것은 안긴문장이 아니라 "…식당이"라는 체언구이다.', '⑤ ㉢의 생략된 성분은 부사어, ㉣의 "아름다운"은 주어("관광지가")가 생략된 관형사절이다.'],
    ref=[8], core='안긴문장의 기능과 생략된 성분의 종류(주어·목적어·필수적 부사어)를 정확히 구별한다.')

add('N-013', 'Ⅱ-B', '선어말 어미의 다양한 쓰임', '상', S % '2023학년도 9월 모의평가 37번',
    p('〈보기〉의 ⓐ~ⓔ에 대한 이해로 적절한 것은?') +
    bogi(['어미는 선어말 어미와 어말 어미로 나뉜다. 선어말 어미는 어간과 어말 어미 사이에 들어가 시제·높임 같은 문법적 의미를 나타내며 하나 혹은 둘 이상이 쓰이거나 아예 쓰이지 않을 수도 있다. 어말 어미에는 종결 어미, 연결 어미, 전성 어미가 있으며, 선어말 어미와 달리 하나만 붙고 반드시 있어야 한다.',
          '○ 머무시는 동안 <u>ⓐ즐거우셨길</u> 바랍니다.', '○ 이 부분에서 물이 <u>ⓑ샜을</u> 가능성이 높다.', '○ <u>ⓒ번거로우시겠지만</u> 서류를 챙겨 주세요.', '○ 시원한 식혜를 먹고 갈증이 싹 <u>ⓓ가셨겠구나</u>.', '○ 항구에 <u>ⓔ다다른</u> 배는 새로운 항해를 준비했다.']),
    ['ⓐ: 선어말 어미 두 개와 연결 어미가 사용되었다.', 'ⓑ: 선어말 어미 없이 전성 어미가 사용되었다.', 'ⓒ: 선어말 어미 세 개와 연결 어미가 사용되었다.', 'ⓓ: 선어말 어미 두 개와 종결 어미가 사용되었다.', 'ⓔ: 선어말 어미 한 개와 전성 어미가 사용되었다.'], 4,
    ['① ⓐ는 즐겁- + -으시- + -었- + -기(명사형 전성 어미) + ㄹ(조사)이다. 어말 어미는 전성 어미이다.', '② ⓑ는 새- + -었-(선어말) + -을(관형사형 전성 어미)이다. 선어말 어미 "-었-"이 쓰였다.', '③ ⓒ는 번거롭- + -으시- + -겠- + -지만(연결 어미)이다. 선어말 어미는 두 개이다.', '④ ⓓ는 가시- + -었- + -겠- + -구나(종결 어미)이다("가시다"의 "시"는 어간의 일부). 선어말 어미 두 개와 종결 어미가 쓰였다.', '⑤ ⓔ는 다다르- + -ㄴ(관형사형 전성 어미)이다. 선어말 어미가 없다.'],
    ref=[3], core='어간 + 선어말 어미(하나 이상 또는 없음) + 어말 어미(하나, 필수)로 쪼갠다.')

add('N-014', 'Ⅱ-B', '부정 표현', '상', S % '2023학년도 9월 모의평가 38번',
    p('〈보기〉의 ㉠, ㉡에 해당하는 예끼리 묶인 것으로 적절한 것은?') +
    bogi(['국어의 부정은 \'안\'/\'-지 않다\'의 의지 부정과 \'못\'/\'-지 못하다\'의 능력 부정이 있다고 알려져 있으나, \'안\'/\'-지 않다\'가 주어의 의지와 무관한 \'단순 부정\'을 나타내는 경우도 많다.',
          '<b>㉠</b> 형용사가 서술어로 쓰이면 \'안\'이나 \'-지 않다\'는 단순 부정을 나타낸다. 형용사가 나타내는 성질·상태에는 주어의 의지가 작용할 수 없기 때문이다.', '<b>㉡</b> 동사가 서술어로 쓰이는 경우에도 주어가 의지를 가지지 못하는 무정물이면 단순 부정을 나타낸다. 또 동사 서술어에 유정물 주어라도 \'나는 깜빡 잊고 약을 안 먹었다.\'처럼 \'안\'이 단순 부정을 나타낼 수 있다.']),
    ['㉠ 옛날엔 통신 기술이 발달하지 않았다. / ㉡ 주문한 옷이 아직도 도착하지 않았다.', '㉠ 이 문제집은 별로 어렵지 않더라. / ㉡ 저는 이 은혜를 잊지 않겠습니다.', '㉠ 나는 그 이야기가 궁금하지 않아. / ㉡ 동생이 오늘 우산을 안 가져갔어.', '㉠ 내 얘기에 고모는 놀라지 않았다. / ㉡ 이 물질은 전기가 통하지 않는다.', '㉠ 밤바다가 그리 고요하지는 않네. / ㉡ 아주 오래간만에 비가 안 온다.'], 5,
    ['① "발달하지"는 동사이므로 ㉠이 아니다.', '② "잊지 않겠습니다"는 유정물 주어의 의지 부정이다(㉡ ×).', '③ "안 가져갔어"는 유정물 주어의 동작이어서 ㉡이라 보기 어렵다(의지 또는 단순 부정으로 갈린다).', '④ "놀라지 않았다"의 "놀라다"는 동사이므로 ㉠이 아니다.', '⑤ "고요하지는"은 형용사(㉠ ○), "비가 안 온다"는 무정물 주어의 동사(㉡ ○)이다.'],
    ref=[7], core='단순 부정: 형용사 서술어, 무정물 주어의 동사. 의지 부정: 유정물 주어 + 동사.')

# ================================================================= 2023 6월 ~ 2020 6월 (pg-051 ~ 058)
add('N-015', 'Ⅱ-B', '피동 표현의 판별', '상', S % '2023학년도 6월 모의평가 39번',
    p('〈보기〉의 ㉠~㉤에 해당하는 예로 적절한 것은?') +
    bogi(['피동문은 능동문과 문법적 관련을 맺는다. 피동문의 서술어는 능동문의 서술어에 피동 문법 요소를 결합해 만든다.',
          '<b>㉠</b> 동사 어근에 피동 접사 \'-이-, -히-, -리-, -기-\'를 결합한다. (예: 접-/접히-)', '<b>㉡</b> 접사 \'-하-\'를 \'-받-, -되-, -당하-\' 등으로 교체한다. (예: 사랑하-/사랑받-)', '<b>㉢</b> 동사 어간에 \'-아지-/-어지-\'를 결합한다. (예: 주-/주어지-)', '<b>㉣</b> \'날씨가 풀리다\'처럼 자연적으로 발생하는 사태를 표현할 때는 대응하는 능동문을 상정하기 어려운 경우가 있다.', '<b>㉤</b> \'없어지다\', \'(거기에) 잘 가지지 않는다\'처럼 \'-아지-/-어지-\'가 형용사나 자동사에 변화의 의미를 더하는 용법은 피동문을 이루지 않는다.']),
    ['㉠: 아버지가 아이에게 점퍼를 입혔다.', '㉡: 그는 친구에게서 선물을 건네받았다.', '㉢: 언론에 의해 사건의 전모가 밝혀졌다.', '㉣: 그 선생님은 학생들에게 존경받는다.', '㉤: 드디어 내 소원이 이루어졌다.'], 3,
    ['① "입혔다"는 "입다"에 "-히-"가 붙은 사동사이다.', '② "건네받다"는 "받다"가 들어간 합성 동사(능동)이다. 접사 교체로 만든 피동이 아니다.', '③ "밝히다"에 "-어지다"가 결합한 피동("밝혀졌다")이다. ㉢에 해당한다.', '④ "존경받다"는 ㉡의 예이다.', '⑤ "이루어졌다"는 타동사 "이루다"에 "-어지다"가 붙은 피동으로 ㉢의 예이다.'],
    ref=[5], core='피동 문법 요소: ① 접사 이·히·리·기 ② -하 → -받·-되·-당하 ③ -아/어지다 ④ 대응 능동문이 없는 피동 ⑤ 변화를 뜻하는 -아/어지다(피동 아님)')

add('N-016', 'Ⅱ-A', '서술어의 자릿수', '상', S % '2022학년도 대학수학능력시험 38번',
    p('밑줄 친 서술어가 요구하는 필수 성분의 개수와 종류가 〈보기〉의 \'<u>유리하다</u>\'와 같은 것은?') + bogi(['이곳의 지형은 외적의 침입을 막기에 <u>유리하다</u>.']),
    ['광물이 귀금속에 <u>속했다</u>.', '그는 바람이 불기에 옷깃을 <u>여몄다</u>.', '우리는 원두막을 하루 만에 <u>지었다</u>.', '나는 시간이 남았기에 그와 <u>걸었다</u>.', '나는 구호품을 수해 지역에 <u>보냈다</u>.'], 1,
    ['〈보기〉 "유리하다"는 주어("지형은") + 필수적 부사어("막기에")를 요구하는 두 자리 서술어이다.', '① "속했다": 주어("광물이") + 필수적 부사어("귀금속에") → 같다.', '② "여몄다": 주어 + 목적어("옷깃을")이다.', '③ "지었다": 주어 + 목적어("원두막을")이다("하루 만에"는 수의적).', '④ "걸었다": 주어만 필요하다("그와"는 수의적).', '⑤ "보냈다": 주어 + 목적어 + 필수적 부사어(세 자리)이다.'],
    ref=[4], core='서술어가 요구하는 필수 성분을 하나씩 빼서 확인한다.')

add('N-017', 'Ⅱ-B', '높임 표현의 종합 분석', '상', S % '2022학년도 9월 모의평가 38번',
    p('〈학습 활동〉의 ㉠에 들어갈 예로 적절한 것은?') +
    bogi(['높임 표현은 홑문장뿐 아니라 겹문장의 안긴문장 속에서도 실현된다. 다음 조건에 맞는 예문을 만들어 보자.']) +
    tbl(['조건', '예문'], [['안긴문장에서의 주체 높임의 대상이 안은문장에서 주어로 실현된 겹문장', '공원에서 산책하시던 할아버지께서 활짝 웃으셨다.'], ['안긴문장에서의 객체 높임의 대상이 안은문장에서 목적어로 실현된 겹문장', '㉠']]),
    ['편찮으시던 어르신께서는 좀 건강해지셨나요?', '오빠는 고향에 계신 부모님을 집으로 모시고 갔다.', '나는 할아버지께서 선물을 주신 날짜를 아직도 기억해.', '누나는 다음 주에 인사를 드릴 할머니께 편지를 썼어요.', '형은 동생이 찾아뵈려던 선생님을 학교에서 만났습니다.'], 5,
    ['① 안긴문장의 주체 높임("편찮으시던")만 있다.', '② "계신"은 주체 높임이고, 객체 높임("모시고")은 안긴문장이 아니라 안은문장에 있다.', '③ "주신"은 주체 높임이다.', '④ 안긴문장 "인사를 드릴"의 객체 높임 대상 "할머니"가 안은문장에서 목적어가 아니라 부사어("할머니께")로 실현되었다.', '⑤ 안긴문장 "찾아뵈려던"의 객체 높임("뵙다") 대상 "선생님"이 안은문장에서 목적어("선생님을")로 실현되었다.'],
    ref=[2], core='안긴문장의 높임 대상이 안은문장에서 어떤 성분으로 나타나는지 확인한다.')

add('N-018', 'Ⅱ-A', '안은문장의 종류', '상', S % '2022학년도 6월 모의평가 37번',
    p('〈학습 활동〉을 수행한 결과로 적절한 것은?') +
    bogi(['다음 흐름도에 따라 [자료]의 ㉮~㉱를 분류할 때, ㉢에 해당하는 것만을 있는 대로 찾아보자.',
          '<b>[흐름도]</b> 안긴문장이 안은문장의 서술어로 쓰이고 있는가? → 예: ㉠ / 아니요: 안긴문장이 안은문장에서 체언을 수식하고 있는가? → 예: ㉡ / 아니요: ㉢',
          '<b>[자료]</b> ㉮ 노래를 부르기가 쉽지 않다. ㉯ 마당에 아무도 모르게 꽃이 피었다. ㉰ 나는 동생이 오기 전에 학교에 갔다. ㉱ 내 동생은 누구보다 마음씨가 착하다.']),
    ['㉮', '㉮, ㉯', '㉰, ㉱', '㉮, ㉯, ㉰', '㉯, ㉰, ㉱'], 2,
    ['㉮ "노래를 부르기가"는 명사절로 서술어도 체언 수식도 아니므로 ㉢이다.', '㉯ "아무도 모르게"는 부사절로 ㉢이다.', '㉰ "동생이 오기"가 체언 "전"을 수식하므로 ㉡이다.', '㉱ "마음씨가 착하다"는 서술절로 ㉠이다. → ㉢은 ㉮, ㉯이다.'],
    ref=[8], core='안긴문장의 기능으로 분류한다: 서술어(서술절) / 체언 수식(관형사절) / 그 밖(명사절·부사절·인용절).')

add('N-019', 'Ⅱ-A', '안은문장의 종류', '상', S % '2021학년도 대학수학능력시험 14번',
    p('〈학습 활동〉을 수행한 결과로 적절하지 <u>않은</u> 것은?') +
    bogi(['겹문장은 안긴문장으로 쓰이거나 안은문장에서 다양한 문장 성분으로 쓰인다. 밑줄 친 ㉠~㉤의 쓰임을 설명해 보자.',
          '<b>㉠</b> <u>내일은 따뜻하지만 비가 온다는</u> 예보를 했다.', '<b>㉡</b> <u>공원이 많고 거리가 깨끗한</u> 도시', '<b>㉢</b> <u>바람이 거세지고 어둠이 내리기</u> 전에', '<b>㉣</b> <u>그녀는 왔으나 그가 안 왔음</u>을 깨달았다.', '<b>㉤</b> <u>꽃이 피고 새가 지저귀는</u> 들판']),
    ['㉠은 인용절이다.', '㉡은 관형절이다.', '㉢은 명사절이다.', '㉣은 조사와 결합하여 주성분으로 쓰였다.', '㉤은 조사와 결합하지 않고 부속 성분으로 쓰였다.'], 1,
    ['① 적절하지 않다. "내일은 따뜻하지만 비가 온다는"은 체언 "예보"를 꾸미는 관형사절(동격절)이다. 인용절이 아니다.', '② 적절하다. "공원이 많고 거리가 깨끗한"은 "도시"를 꾸미는 관형절이다.', '③ 적절하다. "-기"로 끝난 명사절이며 뒤의 "전에"의 앞에서 관형어 노릇을 한다.', '④ 적절하다. "안 왔음"의 "-음"으로 끝난 명사절에 목적격 조사 "을"이 결합해 목적어(주성분)가 되었다.', '⑤ 적절하다. 관형절이 조사 없이 "들판"을 꾸미는 관형어(부속 성분)이다.'],
    ref=[8], core='"-다는 + 체언"은 인용절이 아니라 동격 관형사절일 수 있다. 뒤에 체언이 오는지 확인한다.')

add('N-020', 'Ⅱ-A', '문장 성분의 판별', '상', S % '2021학년도 9월 모의평가 14번',
    p('〈학습 활동〉을 수행한 결과로 적절한 것은?') +
    bogi(['품사는 다양한 방식을 통해 문장 성분으로 실현된다. 품사가 어떻게 문장 성분으로 실현되는지 다음 밑줄 친 부분을 중심으로 알아보자.',
          'ⓐ <u>빵은</u> 동생이 간식으로 제일 좋아한다.', 'ⓑ 형은 <u>아주</u> 옛 물건만 항상 찾곤 했다.', 'ⓒ 나중에 <u>어른</u> 돼서 우리 다시 만나자.', 'ⓓ 친구가 내게 준 선물은 <u>장미였다</u>.', 'ⓔ 다람쥐 <u>세</u> 마리가 나무를 오른다.']),
    ['ⓐ: 명사가 격 조사와 결합해 목적어로 쓰였다.', 'ⓑ: 부사가 관형사를 수식하는 부사어로 쓰였다.', 'ⓒ: 명사가 조사와 결합 없이 주어로 쓰였다.', 'ⓓ: 명사가 어미와 직접 결합해 서술어로 쓰였다.', 'ⓔ: 수사가 명사를 수식하는 관형어로 쓰였다.'], 2,
    ['① "빵은"은 보조사 "은"과 결합한 목적어이다. 격 조사가 아니다.', '② 옳다. "아주"는 부사로, 관형사 "옛"을 수식하므로 부사어이다.', '③ "어른"은 조사 없이 쓰인 보어("되다" 앞)이다. 주어가 아니다.', '④ "장미였다"는 명사 "장미" + 서술격 조사 "이다"이다. 어미와 직접 결합하지 않았다.', '⑤ "세"는 수 관형사이다. 수사가 아니다.'],
    ref=[1], core='품사(단어)와 문장 성분(기능), 조사 결합 여부를 한꺼번에 확인한다.')

add('N-021', 'Ⅱ-A', '안은문장의 종류', '상', S % '2021학년도 6월 모의평가 14번',
    p('〈보기〉의 ㉠~㉤과 관련된 설명으로 적절한 것은?') +
    bogi(['주기적으로 운동하기가 <u>㉠건강의 첫걸음이다</u>. 그것을 꾸준하게 <u>㉡실천하기</u> <u>㉢원한다면</u> 제대로 <u>㉣된</u> 계획 세우기가 <u>㉤선행되어야 한다</u>.']),
    ['㉠이 서술어인 문장에서 명사절이 주어 기능을 하고 있다.', '㉡이 서술어인 문장에서 명사절이 목적어 기능을 하고 있다.', '㉢이 서술어인 문장에서 명사절이 부사어 기능을 하고 있다.', '㉣이 서술어인 문장에서 명사절이 보어 기능을 하고 있다.', '㉤이 서술어인 문장에서 명사절이 관형어 기능을 하고 있다.'], 1,
    ['① 옳다. "주기적으로 운동하기가"는 명사절이 주격 조사와 결합해 서술어 "건강의 첫걸음이다"의 주어가 되었다.', '② "㉡ 실천하기"가 서술어인 문장("그것을 꾸준하게 실천하기")에는 명사절이 없다. 이 절 자체가 "원한다면"의 목적어이다.', '③ "원한다면"의 문장에서는 명사절("그것을 꾸준하게 실천하기")이 목적어이지 부사어가 아니다.', '④ "된"이 서술어인 관형사절 문장에 명사절은 없다.', '⑤ "선행되어야 한다"의 문장에서 명사절("계획 세우기가")은 주어이다. 관형어가 아니다.'],
    ref=[8], core='명사절이 어떤 성분이 되는지는 뒤에 붙은 조사와 서술어의 요구로 판단한다.')

add('N-022', 'Ⅱ-B', '시제의 이해', '상', S % '2020학년도 대학수학능력시험 14번',
    p('〈학습 활동〉을 해결한 내용으로 적절한 것은?') +
    bogi(['관형사형 어미의 형태는 시제와 단어의 품사에 의해 결정된다. [자료]의 밑줄 친 단어의 품사와 시제를 분석하여 [표]의 ㉠~㉢ 중 해당하는 어미를 찾아보자.',
          '<b>[자료]</b> ㉮ 하늘에 <u>뜬</u> 태양 ㉯ 우리가 즐겨 <u>부르던</u> 노래 ㉰ 늘 <u>푸르던</u> 하늘 ㉱ 운동장에 <u>남은</u> 아이들 ㉲ 네가 <u>읽는</u> 소설 ㉳ 이미 아이들로 가득 <u>찬</u> 교실 ㉴ 달리기가 제일 <u>빠른</u> 친구']) +
    tbl(['시제', '동사', '형용사'], [['현재', '-는', '㉠'], ['과거', '㉡ / -던', '㉢'], ['미래', '-(으)ㄹ', '-(으)ㄹ']]),
    ['㉮의 \'뜬\'의 \'-(으)ㄴ\'은 ㉠에 해당한다.', '㉯의 \'부르던\'과 ㉰의 \'푸르던\'의 \'-던\'은 ㉢에 해당한다.', '㉱의 \'남은\'과 ㉳의 \'찬\'의 \'-(으)ㄴ\'은 ㉡에 해당한다.', '㉲의 \'읽는\'의 \'-는\'은 ㉡에 해당한다.', '㉴의 \'빠른\'의 \'-(으)ㄴ\'은 ㉢에 해당한다.'], 3,
    ['표의 ㉠은 형용사 현재 "-(으)ㄴ", ㉡은 동사 과거 "-(으)ㄴ", ㉢은 형용사 과거 "-던"이다.', '① "뜬"은 동사 과거 → ㉡이다.', '② "부르던"은 동사의 "-던", "푸르던"은 형용사의 "-던"(㉢)이다. 둘이 같은 칸이 아니다.', '③ "남은", "찬"은 동사의 과거 "-(으)ㄴ"이므로 ㉡이다. 옳다.', '④ "읽는"은 동사 현재 "-는"이다.', '⑤ "빠른"은 형용사 현재 "-(으)ㄴ"이므로 ㉠이다.'],
    ref=[3], core='관형사형 어미: 동사 현재 -는, 과거 -(으)ㄴ/-던, 형용사 현재 -(으)ㄴ, 과거 -던, 미래 -(으)ㄹ.')

add('N-023', 'Ⅱ-A', '안은문장의 종류', '중', S % '2020학년도 9월 모의평가 15번',
    p('〈보기〉의 ㉠~㉤에 해당하는 문장으로 적절하지 <u>않은</u> 것은?') +
    bogi(['〈자료〉의 홑문장들을 활용해 〈조건〉에 맞는 겹문장을 만들어 보자.']) +
    tbl(['〈자료〉 홑문장', '〈조건〉'], [['날씨가 춥다', '㉠ 명사절을 안은 문장'], ['형은 물을 마셨다', '㉡ 관형절을 안은 문장'], ['동생은 얼음을 먹었다', '㉢ 부사절을 안은 문장'], ['동생은 추위와 상관없다', '㉣ 인용절을 안은 문장'], ['형은 동생에게 불평을 했다', '㉤ 대등하게 이어진 문장']]),
    ['㉠ 동생은 추운 날씨에도 얼음을 먹었다.', '㉡ 형은 얼음을 먹는 동생에게 불평을 했다.', '㉢ 동생은 추위와 상관없이 얼음을 먹었다.', '㉣ 형은 동생에게 날씨가 춥다고 불평을 했다.', '㉤ 형은 물을 마셨지만 동생은 얼음을 먹었다.'], 1,
    ['① 적절하지 않다. "추운 날씨"의 "추운"은 관형사형 어미 "-ㄴ"이 붙은 관형절이다. 명사절은 "-(으)ㅁ", "-기"로 만든다.', '② 적절하다. "(동생이) 얼음을 먹는"이 "동생"을 꾸미는 관형절이다.', '③ 적절하다. "추위와 상관없이"는 "-이"로 만든 부사절이다.', '④ 적절하다. "날씨가 춥다고"는 인용절이다.', '⑤ 적절하다. "-지만"으로 두 절이 대등하게 이어졌다.'],
    ref=[8], core='안긴절의 종류는 어미(표지)로 판단한다: -ㅁ/-기(명사절), -ㄴ/-는(관형절), -이/-게(부사절), -고(인용절).')

add('N-024', 'Ⅱ-B', '피동 표현의 판별', '최', S % '2020학년도 6월 모의평가 15번',
    p('〈보기〉의 ㉠, ㉡에 해당하는 예끼리 묶인 것으로 적절한 것은?') +
    bogi(['<b>[선생님의 설명]</b> 여러분, \'쓰이다\'라는 단어를 어떻게 해석해야 할까요? 우선 \'쓰이다\'는 피동사이기도 하고 사동사이기도 하므로 이를 구별해야겠죠? 또한 \'쓰다\'는 동음이의어나 다의어이므로 그 의미에도 유의해야 합니다. 단어를 이해할 때, 이러한 점들을 모두 고려해야 해요.',
          '<b>[학습 활동]</b> 다음은 국어사전의 일부이다. 제시된 단어의 의미에 유의하여 각각의 피동사와 사동사가 포함된 예를 들어 보자.',
          '<b>갈다¹</b> 【…을 …으로】 ② 어떤 직책에 있는 사람을 다른 사람으로 바꾸다.', '<b>깎다</b> 【…을】 ③ 값이나 금액을 낮추어서 줄이다.', '<b>묻다¹</b> 【…에】 ① 가루, 풀, 물 따위가 그보다 큰 다른 물체에 들러붙거나 흔적이 남게 되다.', '<b>묻다²</b> 【…을】 ② 윗니와 아랫니 사이에 끼운 상태로 상처가 날 만큼 세게 누르다.', '<b>쓸다²</b> 【…을】 ① 비로 쓰레기 따위를 밀어 내거나 한데 모아서 버리다.']) +
    tbl(['피동문', '사동문'], [['㉠', '㉡']]),
    ['㉠: 학생회 임원이 새 친구로 갈렸다. / ㉡: 삼촌이 형에게 그 텃밭을 갈렸다.', '㉠: 용돈이 이달에 만 원이나 깎였다. / ㉡: 나는 저번 실수로 점수를 깎였다.', '㉠: 내 친구는 가래떡에 꿀만 묻혔다. / ㉡: 누나는 붓에 먹물을 듬뿍 묻혔다.', '㉠: 아빠가 아이 입에 사탕을 물렸다. / ㉡: 큰형이 동네 개에게 발을 물렸다.', '㉠: 큰 마당의 눈이 빗자루에 쓸렸다. / ㉡: 내 동생에게 거실 바닥만 쓸렸다.'], 5,
    ['① ㉠의 "갈렸다"는 갈다¹ ②의 피동으로 맞다. ㉡의 "텃밭을 갈렸다"는 땅을 갈다라는 다른 뜻의 사동이어서 제시된 뜻이 아니다.', '② ㉠은 깎다 ③의 피동으로 맞지만, ㉡ "점수를 깎였다"는 사동이 아니라 피동이다.', '③ "묻혔다"는 묻다¹의 사동이므로 ㉠(피동)이 아니다.', '④ "물렸다"는 물다²의 사동이므로 ㉠(피동)이 아니다. ㉡ "개에게 발을 물렸다"는 피동이다.', '⑤ ㉠ "눈이 빗자루에 쓸렸다"는 쓸다² ①의 피동, ㉡ "동생에게 거실 바닥만 쓸렸다"는 쓸다² ①의 사동으로 모두 맞다.'],
    ref=[5, 6], core='같은 모양의 피동·사동 접사는 주어가 직접 당하는지(피동) 시키는지(사동), 사전 뜻풀이와 일치하는지로 판단한다.')
